import tokenomics_logger

from orchestrator import build_orchestrator


QUESTIONS = [
    "How many active projects do we have?",
    "How many clients are in the Northeast region?",
    "What is our onboarding process?",
    "Explain the consultant allocation guidelines.",
    "What is the invoice approval procedure?",
    "How many consultants are assigned to projects?",
    "What is our methodology for project governance?",
    "How much total budget is allocated to active projects?",
    "Describe the process for handling overdue invoices.",
    "How many active projects do we have, and what is our onboarding policy?",
]


orchestrator = build_orchestrator()

for number, question in enumerate(QUESTIONS, start=1):
    print(f"\nQuery {number}: {question}")

    result = tokenomics_logger.run_traced_query(
        orchestrator,
        question,
    )

    print(f"Route: {result.get('route')}")
    print(f"Answer: {result.get('final_answer')}")

tokenomics_logger.print_summary_table()
